/** Health is the response of `GET /healthz`. */
export const HealthSchema = z.object({
  status: z.string(),
  version: z.string(),
})

/** SingboxBuild is what the sing-box binary on the device is built with. */
export const SingboxBuildSchema = z.object({
  /** Tags are the build tags from `sing-box version`. An empty list means a build without tags: node types gated by a tag will be refused by such a binary. */
  tags: z.array(z.string()),
})

/** Runtime is the runtime sources in `GET /api/status`. The fields answer what the daemon can read, not whether sing-box answers now: process liveness goes through `GET /api/service` and the `service` stream topic, and no second truth about it is introduced here. */
export const RuntimeSchema = z.object({
  /** Sources are the sources the daemon assembled. */
  sources: z.array(z.string()),
  /** Connections is the source the panel gets connections from. An empty string means there is nothing to read them with: the screen degrades, and the panel stays available. */
  connections: z.string().optional(),
})

/** Transaction is a snapshot of an apply. It is also the state file format: what the daemon gives to the client and what it replays itself from after a reboot. */
export const TransactionSchema = z.object({
  id: z.string(),
  phase: z.string(),
  /** Window is how much is left for confirmation. Stored as a duration, not as a timestamp: the router has no real-time clock, after power-on it starts from the epoch and jumps on NTP synchronization. */
  window: z.int(),
  /** Sum is the sha256 of the config written by the daemon. It catches an edit of the file from outside. */
  sha256: z.string().optional(),
  /** Lists is the sha256 of the list files the transaction writes: name → fingerprint of the new content. Only the files that really change: by a fingerprint match the replay judges whether the write has started. */
  lists: z.record(z.string(), z.string()).optional(),
  /** RemovedLists are the list files the transaction removes; at the moment of the start they existed. */
  removed_lists: z.array(z.string()).optional(),
  /** ReasonCode is the step at which the cycle stopped. Empty if the apply succeeded or the failure is not tied to a step. */
  reason_code: z.string().optional(),
  /** Reason is filled when the apply did not finish: the original error of the step as the daemon recorded it. Showing it to the user is a fallback path, the panel takes the failure text by ReasonCode. */
  reason: z.string().optional(),
  /** ClashAPIAdded marks that the daemon added the section itself. */
  clash_api_added: z.boolean().optional(),
})

/** Status is the response of `GET /api/status`. */
export const StatusSchema = z.object({
  /** Version is the daemon version; the sing-box binary version is a separate field. */
  version: z.string(),
  singbox_version: z.string().optional(),
  /** SingboxBuild is the binary build composition. No field means the binary was not read, and the panel has nothing to judge which node types are missing in it by. */
  singbox_build: SingboxBuildSchema.optional(),
  /** ConfigPath is the file the daemon owns: the path is set by start flags, and the panel side cannot compute it. */
  config_path: z.string().optional(),
  /** ConfirmWindowSeconds is how long an apply waits for confirmation before the rollback, from the `-confirm-window` start flag. */
  confirm_window_seconds: z.int(),
  /** Runtime is where the daemon reads the runtime from. A silent swap of one source for another is forbidden, so the composition is declared by the contract. */
  runtime: RuntimeSchema,
  transaction: TransactionSchema.optional(),
  /** TransactionHref is the address of the running apply. Without it a page reload loses the transaction: its identifier lived only in the response to POST. */
  transaction_href: z.string().optional(),
  /** DataplaneTransaction is the last dataplane model change in this daemon lifetime. It goes by the same protocol and with the same phases as a config apply, and never runs at the same time as it. */
  dataplane_transaction: TransactionSchema.optional(),
  /** DataplaneTransactionHref is the address of the dataplane change, by the same rule as TransactionHref. */
  dataplane_transaction_href: z.string().optional(),
})

/** Version is a history entry. The daemon does not parse the config content, so only the number, size, fingerprint and timestamp go outside. */
export const VersionSchema = z.object({
  /** ID is a monotonic number. Time cannot be the source of order: the router has no real-time clock, it starts from the epoch and jumps on NTP synchronization. */
  id: z.int(),
  /** Size is the size in bytes. */
  size: z.int(),
  /** Sum is the sha256 of the content. It shows that the version matches the active config without reading both. */
  sum: z.string(),
  /** SavedAt is the file timestamp, Unix seconds. Informational: shows the device clock at the time of saving and lies if it is not synchronized. */
  saved_at: z.int(),
  /** ListsSum is the fingerprint of the list files snapshot in the same notation as the etag of `GET /api/config/rule-sets`. No field means the version was saved without a snapshot, and its restore does not touch the lists. */
  lists_sum: z.string().optional(),
})

/** Versions is the response of `GET /api/config/versions`. */
export const VersionsSchema = z.object({
  versions: z.array(VersionSchema),
  /** CurrentSum is the sha256 of the applied config in the same notation as `Version.Sum`: the panel marks the version matching the file on the device by it. Computed by the daemon because the browser gives `crypto.subtle` only in a secure context, and the panel is opened over http. No field means there is no config on the device. */
  current_sum: z.string().optional(),
  /** CurrentListsSum is the fingerprint of the current list file set in the same notation as `Version.ListsSum`: a version matches the device only when both the config and the lists match. The field is absent from a daemon that does not store list snapshots. */
  current_lists_sum: z.string().optional(),
})

/** Service is the response of `GET /api/service` and an event of the same form in the stream: the panel gets one format regardless of the source. */
export const ServiceSchema = z.object({
  status: z.string(),
  /** Uptime is seconds since the start. Zero means the age could not be learned: the panel shows such a value as a dash. */
  uptime: z.int(),
  /** Binary is the binary version on the device. The panel knows its own schema and checks the mismatch itself. */
  binary: z.string(),
  /** Managed means the process is owned by the service the daemon manages. False with the status `running` reads as: sing-box on the device works, but was started not by it: routing is owned by a foreign package, and the service buttons do not apply to this process. */
  managed: z.boolean(),
  lastError: z.string().optional(),
  /** LastErrorCode is why LastError was written by the daemon and not by the service. Empty when LastError holds the output of a failed service: the panel shows it verbatim. */
  lastErrorCode: z.string().optional(),
})

/** Point is the average speed per step, bytes per second. */
export const PointSchema = z.object({
  down: z.int(),
  up: z.int(),
})

/** DevicePoint is the board and process readings per step. Load and temperature are taken as the step peak, memory as the average. The history is needed to notice overheating and a leak over days of work, and on step coarsening the average would dissolve a short overheating among neighbouring calm minutes. */
export const DevicePointSchema = z.object({
  /** Load is the average load per minute as the kernel gives it; the step peak. */
  load: z.number(),
  /** Celsius is the hottest board zone, the step peak; zero means there are no zones. */
  celsius: z.number(),
  /** Memory is the occupied board memory in bytes. */
  memory: z.int(),
  /** Singbox is the resident memory of the sing-box process in bytes; zero means the process was not found. A leak is visible by it: the board memory as a whole blurs it. */
  singbox: z.int(),
  /** Daemon is the resident memory of the daemon itself in bytes. */
  daemon: z.int(),
})

/** History is the response of `GET /api/history`: traffic over the whole time the daemon accumulated. The point time is not transmitted: the router has no clock before NTP synchronization, and an absolute stamp would lie. The points go in sequence with the step StepSeconds, the last is the freshest, and the axis labels are computed by the panel from its own clock. */
export const HistorySchema = z.object({
  step_seconds: z.int(),
  points: z.array(PointSchema),
  /** Device is the board readings with the same step: load, temperature, memory. */
  device: z.array(DevicePointSchema),
  /** Recent is the last minute of traffic per second, without averaging. Empty until the daemon has received a single sample. */
  recent: z.array(PointSchema),
  /** Connections is the number of live connections over the last minute, one snapshot per second. */
  connections: z.array(z.int()),
})

/** Error is the single failure format at the HTTP boundary. Internal details (paths on disk, command arguments, config content) do not get into it; Details carries only what is shown to the user. Code is the contract, Message is a fallback text: the panel shows its own translation by the code, and takes the message only when the code is unfamiliar to it. */
export const ErrorSchema = z.object({
  code: z.string(),
  message: z.string(),
  details: z.unknown().optional(),
})

/** CheckDetails is the sing-box output verbatim. The only exception to the rule "internal details do not go outside": the user fixes the config by these lines. */
export const CheckDetailsSchema = z.object({
  stdout: z.string(),
  stderr: z.string(),
  exit_code: z.int(),
})

/** WorkdirDetails are the directories of the `workdir_mismatch` failure. Paths go outside deliberately: the panel knows the config path from `GET /api/status` anyway, and by these two it builds the command that configures the service. */
export const WorkdirDetailsSchema = z.object({
  /** Workdir is the working directory procd starts the service with. */
  workdir: z.string(),
  /** ConfigDir is the config directory the daemon owns. */
  config_dir: z.string(),
})

/** RuleSetFiles are the own list files from the rule-sets subdirectory of the config directory, as GET /api/config/rule-sets returns them. */
export const RuleSetFilesSchema = z.object({
  /** Files is the file name → content byte for byte. */
  files: z.record(z.string(), z.string()),
  /** Etag is the set fingerprint; the client returns it in lists_base of the apply. */
  etag: z.string(),
})

/** ApplyEnvelope is a config apply together with the list files of the rule-sets subdirectory. Goes in POST /api/apply with Content-Type application/vnd.metabox.apply+json; a body without this type the daemon reads as bare config bytes. */
export const ApplyEnvelopeSchema = z.object({
  /** Config is the config text as is, with comments and dangling commas. */
  config: z.string(),
  /** Lists is the file name in the rule-sets subdirectory → its content. */
  lists: z.record(z.string(), z.string()).optional(),
  /** RemoveLists are the rule-sets subdirectory files the apply deletes. */
  remove_lists: z.array(z.string()).optional(),
  /** ListsBase is the fingerprint of the file set the client edited from: the etag value from GET /api/config/rule-sets. Empty means apply without a check. */
  lists_base: z.string().optional(),
})

/** Device is a LAN device reduced by MAC. */
export const DeviceSchema = z.object({
  /** IP is the address from the lease, and without it from the static entry. Empty when there is no address in either: the device has only its own name. */
  ip: z.string(),
  /** MAC is lowercase with colons; the own name is stored by it. */
  mac: z.string(),
  /** Name is the label by priority: own name, static lease, DHCP. Empty with NameSource `none`. */
  name: z.string(),
  /** NameSource is where the label comes from; with `none` the panel labels the device with its address. */
  name_source: z.string(),
  /** Static means the MAC has a static lease in UCI `dhcp`. */
  static: z.boolean(),
  /** Online means the lease has not expired by the router clock. Before NTP synchronization the clock stands in the past, and an expired lease may count as alive. */
  online: z.boolean(),
  /** LeaseExpires is the lease end in unix seconds. Zero means no lease or it is permanent; the second differs by the Online flag. */
  lease_expires: z.int(),
})

/** Devices is the response of `GET /api/devices` and `PUT /api/devices/{mac}`: LAN devices by address, those without an address at the end. */
export const DevicesSchema = z.object({
  devices: z.array(DeviceSchema),
})

/** DeviceName is the body of `PUT /api/devices/{mac}`. */
export const DeviceNameSchema = z.object({
  /** Name is the own device name. Empty removes it, and the label returns to the static lease or DHCP. */
  name: z.string(),
})

/** Model is the `metabox.dataplane` section. A missing option gets the default value from Defaults; a list set with empty values is empty. */
export const ModelSchema = z.object({
  /** Enabled is whether to install interception. False: the service starts only sing-box, without nft, ip rule and the dnsmasq upstream. */
  enabled: z.boolean(),
  /** RedirectPort is the redirect inbound port: LAN TCP goes here. */
  redirect_port: z.int(),
  /** TproxyPort is the tproxy inbound port: LAN UDP goes here. */
  tproxy_port: z.int(),
  /** DNSPort is the sing-box dns-in port that dnsmasq sends queries to. */
  dns_port: z.int(),
  /** DNSHijack is whether to intercept udp/53 from the LAN to the router dnsmasq. */
  dns_hijack: z.boolean(),
  /** SelfMark is the bypass mark: a packet with it goes around interception. Matches route.default_mark of the sing-box config, otherwise its traffic would loop. */
  self_mark: z.int(),
  /** TproxyMark is the mark of tproxy flows, ip rule sends them to RouteTable by it. */
  tproxy_mark: z.int(),
  /** RouteTable is the routing table with a local route for tproxy. */
  route_table: z.int(),
  acl_mode: z.string(),
  /** SourceIP are the sources of listed mode: an IPv4 address or a subnet. */
  source_ip: z.array(z.string()),
  /** SourceMAC are the sources of listed mode by MAC: they do not depend on a lease change. */
  source_mac: z.array(z.string()),
  /** LANInterface are the interfaces traffic is intercepted from. */
  lan_interface: z.array(z.string()),
  /** WANProxyCIDR are the destinations that always go through sing-box. */
  wan_proxy_cidr: z.array(z.string()),
  /** WANDirectCIDR are the destinations that always bypass sing-box. */
  wan_direct_cidr: z.array(z.string()),
  /** IPv6 is whether to render the IPv6 chains; while false, there are none. */
  ipv6: z.boolean(),
})

/** Dataplane is the response of `GET /api/dataplane`: the dataplane model from UCI and whether its rules stand on the device. */
export const DataplaneSchema = z.object({
  model: ModelSchema,
  /** Applied means the dataplane chains are in the fw4 table. False without AppliedReason means nft was read and there are no chains. */
  applied: z.boolean(),
  /** AppliedReason is why Applied was not observed but substituted with false. */
  applied_reason: z.string().optional(),
  /** ForeignService means the daemon manages not the `metabox-singbox` service, and `PUT /api/dataplane` will get `dataplane_foreign_service`: the panel does not offer a change the daemon will reject. */
  foreign_service: z.boolean().optional(),
})

/** DataplaneChange is the body of `PUT /api/dataplane`: the model in the same form as the model field of the `GET /api/dataplane` response. Written whole: a missing field is a zero value, not "leave as is". */
export const DataplaneChangeSchema = z.object({
  model: ModelSchema,
})

/** FieldError is one value that was not accepted. */
export const FieldErrorSchema = z.object({
  /** Field is the UCI option name. */
  field: z.string(),
  /** Value is the value as in UCI; for a list element, the element itself. Empty for ReasonRequired. */
  value: z.string(),
  reason: z.string(),
})

/** DataplaneDetails are the fields of the `dataplane_invalid` failure. */
export const DataplaneDetailsSchema = z.object({
  fields: z.array(FieldErrorSchema),
})

/** Entry is a sing-box log line. */
export const EntrySchema = z.object({
  /** Time is the line timestamp in RFC 3339; empty when there is no stamp. For logger lines this is the logd time, for the file the sing-box log.timestamp stamp. The router has no real-time clock: before NTP synchronization the stamps are in the past. */
  time: z.string().optional(),
  /** Level is empty when the level is not parsed: a continuation of a multi-line message, a panic stack. The level filter lets such lines through. */
  level: z.string().optional(),
  message: z.string(),
})

/** Logs is the response of `GET /api/logs`: the last sing-box log lines, old first. */
export const LogsSchema = z.object({
  source: z.string(),
  /** Since is the last cleanup mark in RFC 3339: lines earlier than it are not returned. No field means there was no cleanup since the daemon start. */
  since: z.string().optional(),
  entries: z.array(EntrySchema),
})

/** LogEvent is the `log` event of the `GET /api/logs/stream` stream. */
export const LogEventSchema = z.object({
  /** Seq grows by one with each line, including one dropped because of a slow reader: a gap means lost lines. */
  seq: z.int(),
  entry: EntrySchema,
})

/** LogsCleared is the response of `POST /api/logs/clear`. */
export const LogsClearedSchema = z.object({
  /** Since is the cleanup mark in RFC 3339. */
  since: z.string(),
})

/** Auth is the response of `GET /api/auth`. */
export const AuthSchema = z.object({
  /** Enabled means the panel has a password: without a session every API request except the health check and the login endpoints gets 401. */
  enabled: z.boolean(),
  /** Authenticated means the request came with a live session. Always false without a password. */
  authenticated: z.boolean(),
})

/** Login is the body of `POST /api/auth/login`. */
export const LoginSchema = z.object({
  password: z.string(),
})

/** PasswordChange is the body of `PUT /api/auth/password`. A successful set or change closes every session and opens a new one for the caller in the cookie; removal closes every session. */
export const PasswordChangeSchema = z.object({
  /** Current is the password in force. Ignored while the panel has no password. */
  current: z.string(),
  /** Password is the new password, 8 to 128 characters. Empty removes the password. */
  password: z.string(),
})

/** MCP is the response of `GET /api/mcp`. */
export const MCPSchema = z.object({
  /** Enabled means the endpoint serves a request with the token. While false it answers 404, as an unknown path. */
  enabled: z.boolean(),
  /** Endpoint is the path of the MCP endpoint on the panel address. */
  endpoint: z.string(),
  /** Permissions are what the token allows. Empty while MCP is disabled. */
  permissions: z.array(z.string()),
})

/** MCPToken is the response of `POST /api/mcp/token`: a new token, which enables MCP and invalidates the previous token. The daemon keeps only its hash, so the token is shown once; the agent sends it as `Authorization: Bearer <token>`. */
export const MCPTokenSchema = z.object({
  token: z.string(),
  endpoint: z.string(),
  permissions: z.array(z.string()),
})

/** Load is the average load. It cannot be converted to percent: it is the run queue length, and on four cores a value of 4.0 means full occupancy. */
export const LoadSchema = z.object({
  one: z.number(),
  five: z.number(),
  fifteen: z.number(),
  /** Cores is how many cores the system sees: without it the value cannot be read. */
  cores: z.int(),
})

/** Memory is the device memory in bytes. */
export const MemorySchema = z.object({
  total: z.int(),
  /** Available is what the system is ready to give without swap, not `MemFree`: free memory on a router is always small, the cache takes the rest. */
  available: z.int(),
})

/** Zone is one kernel thermal zone. */
export const ZoneSchema = z.object({
  /** Name is the `type` of the zone: a board may have several, and they differ by it. */
  name: z.string(),
  /** Milli is thousandths of a degree Celsius, exactly as the kernel gives it. */
  milli: z.int(),
})

/** Link is the interface counters since it came up, in bytes. */
export const LinkSchema = z.object({
  name: z.string(),
  rx: z.int(),
  tx: z.int(),
})

/** Share is how much passed through the channel and through sing-box during the observation. The share is computed by dividing one by the other and is meaningful only together with Seconds: the window starts when the daemon first took readings. */
export const ShareSchema = z.object({
  link: z.int(),
  proxy: z.int(),
  seconds: z.int(),
})

/** Process is the readings of a foreign process. */
export const ProcessSchema = z.object({
  pid: z.int(),
  /** RSS is the resident memory of the process in bytes. For sing-box it is larger than `memory` from the Clash API: that one gives only the Go runtime memory, while here it is the whole process together with the resident code of the binary. */
  rss: z.int(),
})

/** Daemon is the readings of metaboxd itself. */
export const DaemonSchema = z.object({
  rss: z.int(),
  heap: z.int(),
  goroutines: z.int(),
})

/** Stat is the device readings at the time of the poll. */
export const StatSchema = z.object({
  load: LoadSchema,
  memory: MemorySchema,
  /** Thermal is empty when the board has no thermal zones. */
  thermal: z.array(ZoneSchema),
  /** Uplink is empty when there is no default route. */
  uplink: LinkSchema.optional(),
  /** Share is the volumes of the channel and of sing-box during the daemon observation. */
  share: ShareSchema,
  /** Singbox is empty when the process is not found: there may be no routing on the device at all. */
  singbox: ProcessSchema.optional(),
  daemon: DaemonSchema,
  /** Uptime is seconds since the device booted. */
  uptime: z.int(),
})

/** Check is one check. */
export const CheckSchema = z.object({
  name: z.string(),
  status: z.string(),
  /** Reason is empty when ok. */
  reason: z.string().optional(),
  /** Detail is a detail in the daemon's language: port, original error, Clash API answer. The panel shows it under its own text, not instead of it. */
  detail: z.string().optional(),
  /** Missing are the absent chains with chains_missing. */
  missing: z.array(z.string()).optional(),
  /** DelayMS is the delay with ok for proxy and direct. */
  delay_ms: z.int().optional(),
})

/** Report is a report with the checks in a fixed order. */
export const ReportSchema = z.object({
  checks: z.array(CheckSchema),
})

/** Connection is a connection in the daemon contract. The panel shape does not depend on which source the connection was read from: the Clash API and the fork gRPC differ both in the field set and in the rule format, so the reduction to one model is done by the daemon, not the frontend. */
export const ConnectionSchema = z.object({
  id: z.string(),
  /** Host is the destination address with a port: the name if sniff parsed it, otherwise the address. Built here because the sources keep it differently. */
  host: z.string(),
  network: z.string(),
  source: z.string(),
  /** Rule is the conditions of the matched rule. Empty for a rule without conditions and for a connection that matched none. */
  rule: z.string(),
  /** Action is the rule outbound: an outbound or an action. gRPC does not return it at all, and the field is empty there. */
  action: z.string(),
  /** Final marks that no rule matched and route.final fired. Without a separate flag this outbound cannot be told from a rule without conditions: both have empty conditions, but these are different things. */
  final: z.boolean(),
  /** Chain is the chain in core order: from the final node to the group. */
  chain: z.array(z.string()),
  upload: z.int(),
  download: z.int(),
  started_at: z.string(),
})

/** ConnectionsSnapshot is the full list of live connections with totals. */
export const ConnectionsSnapshotSchema = z.object({
  connections: z.array(ConnectionSchema),
  upload_total: z.int(),
  download_total: z.int(),
  memory: z.int(),
})

/** Event is an envelope. Seq is counted for each reader separately and grows without gaps while events arrive: a gap in numbers means the reader could not keep up and an event was dropped. */
export const EventSchema = z.object({
  topic: z.string(),
  seq: z.int(),
  data: z.unknown(),
})

/** Match is the matched rule. Index is returned by pointer: zero is a valid index, and it cannot otherwise be told from "no index". */
export const MatchSchema = z.object({
  origin: z.string(),
  kind: z.string(),
  index: z.int().optional(),
  conditions: z.string().optional(),
  action: z.string().optional(),
  /** ReasonCode is filled only for Kind == KindUnknown: the panel takes the text in the user's language by it. */
  reason_code: z.string().optional(),
  /** Reason is the same reason in the daemon's words. A fallback text for a code the panel does not know. */
  reason: z.string().optional(),
})

/** Chain is the proxy chain of a connection in the order core returns it: from the final node to the group. */
export const ChainSchema = z.object({
  origin: z.string(),
  nodes: z.array(z.string()),
})

/** Rule is a rule of the running process. The index equals the node index in route.rules of the applied document: the router builds the list by a loop over the config one to one. */
export const RuleSchema = z.object({
  origin: z.string(),
  index: z.int(),
  type: z.string(),
  conditions: z.string(),
  action: z.string(),
})

/** Explanation is the response of the route explanation handler. */
export const ExplanationSchema = z.object({
  connection_id: z.string(),
  match: MatchSchema,
  chain: ChainSchema,
  /** Rules is the whole list of the running process. The panel compares its length with the length of route.rules of the applied document: the process could have loaded another config, and leading the user to a node of a foreign file is not allowed. */
  rules: z.array(RuleSchema),
})

/** RuleHits are the hits of one rule of the running process. */
export const RuleHitsSchema = z.object({
  index: z.int(),
  hits: z.int(),
  /** Counted is whether the rule is visible in the connection list at all. The Clash API writes for a connection only the rule on which the iteration stopped, and only for connections that went to an outbound: `sniff` and `resolve` do not stop the iteration, an intercepted DNS and a rejected connection do not get into the list. For such rules zero would mean not "did not fire" but "not visible". */
  counted: z.boolean(),
})

/** Hits is the response of the rule hit counter handler. The count is observed, not exact: a connection that opened and closed between two snapshots will no longer be shown by core and will not get into the count. */
export const HitsSchema = z.object({
  /** Seconds is how long the count has been running. It lives in the daemon memory and starts with its start: the router has no real-time clock, so a duration is returned, not a start moment. */
  seconds: z.int(),
  /** Rules is an entry for each rule of the running process, in its order. The panel compares the length with route.rules of the applied document, as with the route explanation. */
  rules: z.array(RuleHitsSchema),
  /** Final counts connections that matched no rule and went to route.final. */
  final: z.int(),
})

/** Mirror is the address from which sing-box downloads the set files. The primary address is not always reachable from Russia, so there are several mirrors. */
export const MirrorSchema = z.object({
  id: z.string(),
  name: z.string(),
  /** Base is the start of the address up to the file name, with a trailing slash. */
  base: z.string(),
})

/** List is one kind of lists at a provider. */
export const ListSchema = z.object({
  kind: z.string(),
  /** Prefix is the file name prefix: `geosite-` + category + `.srs`. */
  prefix: z.string(),
  mirrors: z.array(MirrorSchema),
  /** Featured is what to show while the category field is empty, in order from general to specific. */
  featured: z.array(z.string()),
  /** Categories are all categories for which the provider has an `.srs` file, alphabetically. */
  categories: z.array(z.string()),
  source: z.string(),
  /** UpdatedAt is when the listing was last checked with the provider, and for a snapshot when it was built; Unix seconds. An informational value: the router has no real-time clock, but the check goes over TLS, which does not pass without synchronized clocks. */
  updated_at: z.int(),
})

/** Provider is a provider of ready sets. */
export const ProviderSchema = z.object({
  id: z.string(),
  name: z.string(),
  lists: z.array(ListSchema),
})

/** Catalog is the catalog handler response. */
export const CatalogSchema = z.object({
  providers: z.array(ProviderSchema),
})

